import {createGame} from './engine.mjs';
import {mountRiskPanel} from './risk-view.mjs';
const lang=localStorage.getItem('moneyLabLanguage')==='en'?'en':'vi',vi=lang==='vi',t=(a,b)=>vi?a:b,$=s=>document.querySelector(s);document.documentElement.lang=lang;
$('#riskTitle').textContent=t('Hiểu quy tắc. Kiểm tra quyết định.','Understand the rule. Check the decision.');$('#riskIntro').textContent=t('Phòng thí nghiệm tài chính dùng dữ liệu mạch TapeOut trên X Layer. Đây là các tình huống minh họa cố định, không phải lịch sử người chơi.','A financial decision lab using TapeOut circuit data on X Layer. These fixed illustrative scenarios are not player records.');$('#scenarioLabel').textContent=t('Chọn một tình huống','Choose a scenario');['balanced','thin','stop'].forEach((v,i)=>$('#scenario').options[i].text=t(['Có khoảng đệm','Dự phòng mỏng','Cổng STOP đang khóa'][i],['A financial buffer','Thin emergency reserve','STOP gate is active'][i]));$('#scenarioNote').textContent=t('Các phép thử không mở chặng, không trả thưởng, không thay đổi HUB hoặc dữ liệu chơi thật. Chỉ bấm đối chiếu mới đọc RPC; không cần ví.','Experiments start no stage, earn no reward and change no HUB or real gameplay data. Only verification reads RPC; no wallet is needed.');$('#layersTitle').textContent=t('Bằng chứng xác nhận điều gì?','What does each piece of evidence establish?');$('#layerLabel').textContent=t('Lớp','Layer');$('#scopeLabel').textContent=t('Phạm vi','Scope');$('#layers').innerHTML=(vi?[['Money Lab','Tính USD giả lập, nghĩa vụ, dự phòng và 3 điều kiện đầu vào.'],['TapeOut #48 · mainnet','Đọc NAND thật tại một khối. Ghép quy tắc ngoài chain; không xác thực nguồn dữ liệu tiền.'],['Replay Decision','Đổi một lựa chọn và giữ chuỗi sự kiện đã ghi; không thay thưởng.'],['Kết quả testnet','Đối chiếu hash nhật ký và điểm/thưởng với hợp đồng máy chủ ký. Không phải thực thi game phi tập trung.'],['REF design · chưa triển khai','4 tham chiếu tới mạch #48; tải bản nháp và kiểm tra 8 tổ hợp, chưa có circuit ID mới.']]:[['Money Lab','Calculates simulated USD finances and three input conditions.'],['TapeOut #48 · mainnet','Reads actual NAND outputs at one block. Offchain composition does not attest financial inputs.'],['Replay Decision','Changes one choice using recorded events, without changing rewards.'],['Testnet result','Matches journal hash and outcome to the server-attested contract result. Not decentralized gameplay.'],['REF design · not deployed','Four references to circuit #48; downloadable draft with eight-vector checks, no new circuit ID.']]).map(([a,b])=>`<tr><th>${a}</th><td>${b}</td></tr>`).join('');$('#riskNext').textContent=t('DeWEB/TapeKit và TapeSend vẫn thuộc hướng nghiên cứu; Money Lab hiện chưa được lưu trữ hoặc nhắn tin bằng các công cụ này.','DeWEB/TapeKit and TapeSend remain research directions; Money Lab currently uses neither for hosting or messaging.');
function render(){const scenario=$('#scenario').value,s=createGame('medium');s.started=true;s.runId='risk-example-'+scenario;if(scenario==='thin'){s.cash=1500;s.reserve=500;}if(scenario==='stop'){s.cash=1500;s.reserve=0;s.gate={IN0:1,IN1:1,OUT0:0};}mountRiskPanel(s,lang,{source:'illustrative-example'});}$('#scenario').onchange=render;$('#riskLanguage').onclick=()=>{localStorage.setItem('moneyLabLanguage',vi?'en':'vi');location.reload();};render();
